		contents: "---\n/*\n * specorator-template-version: 1\n *\n * Dynamic listing route (docs/DESIGN.md §5.5). One static page per committed\n * snapshot, addressed by the snapshot's authoritative listing `route` (the\n * collection entry id, e.g. `/books`). `getStaticPaths()` enumerates the\n * `snapshots` collection; each page dispatches to a view component via the\n * stable registry barrel (`registry.ts`) using `render.component`, defaulting\n * to the view `type` when the binding is `'auto'` (§5.6). The registry barrel\n * keeps the file set stable so new components dodge Astro's new-file HMR gap\n * (D9). Per-entry detail pages are C8 — out of scope here (listings only).\n */\nimport { getCollection } from 'astro:content';\nimport { resolveLayout, resolveView } from '../registry';\nimport type { ViewSnapshot } from '../content/schema';\n\nexport async function getStaticPaths() {\n\tconst entries = await getCollection('snapshots');\n\treturn entries.map((entry) => {\n\t\t// The entry id is the leading-slash listing route (e.g. `/books`); Astro's\n\t\t// `[...slug]` param is slash-relative, so strip the leading slash.\n\t\tconst slug = entry.id.replace(/^\\/+/, '');\n\t\treturn { params: { slug }, props: { snapshot: entry.data } };\n\t});\n}\n\ninterface Props {\n\tsnapshot: ViewSnapshot;\n}\n\nconst { snapshot } = Astro.props;\n\n// Resolve the component: an explicit binding wins; `'auto'` (or anything\n// unresolved) falls back to the native view type (`table`/`cards`/`list`).\nconst componentName =\n\tsnapshot.render.component && snapshot.render.component !== 'auto'\n\t\t? snapshot.render.component\n\t\t: snapshot.view.type;\n\nconst View = resolveView(componentName);\nconst layoutName =\n\tsnapshot.render.layout && snapshot.render.layout !== 'auto'\n\t\t? snapshot.render.layout\n\t\t: 'BaseLayout';\nconst Layout = resolveLayout(layoutName);\n---\n\n<Layout title={snapshot.view.name}>\n\t<header class=\"sp-listing-header\">\n\t\t<h1>{snapshot.view.name}</h1>\n\t</header>\n\t<View snapshot={snapshot} />\n</Layout>\n\n<style>\n\t.sp-listing-header h1 {\n\t\tcolor: var(--sp-color-fg);\n\t\tmargin-top: 0;\n\t}\n</style>\n",
